arr=[]
for fn, titles in [('E01.json',E01),('E02.json',E02),('E03.json',E03)]:
 data=json.load(open(p/fn,encoding='utf-8'))
 assert len(data)==40 and len(titles)==40
 arr += [{'id':x['id'],'title_main':t} for x,t in zip(data,titles)]
out=p/'prefix_patch_E01_E03.json'
out.write_text(json.dumps(arr,ensure_ascii=False,indent=2),encoding='utf-8')
# validation
assert len(arr)==120
assert len({x['id'] for x in arr})==120
assert len({x['title_main'] for x in arr})==120
assert all(8<=len(x['title_main'])<=16 for x in arr)
expected=[x['id'] for fn in ['E01.json','E02.json','E03.json'] for x in json.load(open(p/fn,encoding='utf-8'))]
assert {x['id'] for x in arr}==set(expected)
print('validated',len(arr),len({x['id'] for x in arr}),len({x['title_main'] for x in arr}))
